from collections import deque

def get_longest_triplet_length(road_pairs):
    n = len(road_pairs)
    dp = [[0] * 2 for _ in range(n)]
    path = deque()

    def expand_triplet(road_pairs, path, n):
        path_length = len(path)
        if path_length == 3:
            triplet = tuple(path)
            if dp[triplet[0]][0] + dp[triplet[1]][1] + dp[triplet[2]][1] <= 2 * len(triplet):
                return road_pairs
            return expand_triplet(road_pairs, queue, n)

        new_paths = []
        for i in range(path_length):
            new = list(path)
            if i + 2 < path_length:
                new[random.randint(i + 2, path_length) % len(path)] = new.pop(i + 2)
                new_paths.append(tuple(new))

        res = [expand_triplet(new, new_paths, n) for new in new_paths]

        min_length = min(len(new) for res in res for new in res)
        return deque(one for res in res for new in res if len(new) == min_length)

    tripleds = [road_pairs[i:i+3] for i in range(0, len(road_pairs), 3)]
    queue = expand_triplet(triplets, deque([]), n)
    while queue:
        road_pairs_length = 0
        for road in queue:
            road_pairs_length += road[2]
        if road_pairs_length != 10**18:
            return road_pairs_length
        queue = expand_triplet(queue, queue.dq.peek(), len(road_pairs))
    return -1
