def can_make_symmetric(H, W, S):
    # Initialize a counter for row differences
    row_diff_count = 0
    # Initialize a counter for column differences
    col_diff_count = 0

    # Determine the maximum length of the strings possible
    max_string_length = min(H, W - 1)

    for i in range(H):
        for j in range(W):
            # Check if row i starting at column j is different from the mirrored row and column
            if S[i][j] != S[H - 1 - i][W - 1 - j]:
                row_diff_count += 1
            # Check if column j starting at row i is different from the mirrored column and row
            if S[i][j] != S[H - 1 - i][j]:
                col_diff_count += 1

    # If there are any differences, it's not symmetric
