import sys

def max_route_length(m, edges):
    if m < 2:
        return -1

    num_towns = 1
    max_length = 2

    for i in range(2, 501):
        candidates = []
        for end, type in edges:
            if end < num_towns and i - num_towns >= 0:
                candidates.extend([[i, type, 1], [i, 1, type]])
                if end < i:
                    candidates.append([i, 0, 1])
                    candidates.append([i, 1, 0])

            if end == num_towns:
                candidates.extend([[i, 0, 0], [i, 0, 1], [i, 1, 0]])
                candidates.extend([[i, 1, 1]])

        candidates.sort()

        for items in candidates:
            num_towns += items[1]
            max_length = max(max_length, num_towns - num_towns % 2 + 1)
            num_towns += items[2]

    return max_length

