    for word in f:
        dictionary.add(word.strip())

def is_mistyped(word):
    for i in range(len(word)):
        for j in range(i + 1, len(word)):
            if word[i] != word[j]:
                if is_mistyped(word[:i] + word[j:] + word[i + 1:j] + word[i] + word[j + 1:]):
                    return True
                break
            if is_mistyped(word[:i] + word[j] + word[i + 1:]):
                return True
    return False

def correct(word, idx, start):
    while idx < len(word) and start < len(dictionary):
        if word[idx] == dictionary[start]:
            start += 1
        idx += 1

    if idx == len(word):
        return word

    pos = -1
    for i in range(idx - 1, -1, -1):
        if is_mistyped(word[idx:i + 1]):
            pos = i
            break

    if pos == -1:
        return word

    corrected_word = correct(word, idx, start)
    if corrected_word == word:
        return corrected_word

    new_word = corrected_word.replace(word[idx - pos:idx], dictionary[start])
    return new_word

def main():
