from collections import deque

def bfs(start, goals, time, obstacles):
    # Initialize the BFS queue
    queue = deque([(start, [start], 0)])
    visited = set()
    visited.add(start)

    while queue:
        current, path, time_taken = queue.popleft()

        # If we've reached a goal, return the time
        if goals in path:
            return time_taken

        # Explore adjacent cells
        for i in range(len(path)):
            cell = path[i]
            neighbors = get_neighbors(cell, obstacles)
            for neighbor in neighbors:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path[:i] + [cell] + path[i+1:], time_taken + time[current // m][cell // m][next((neighbor // m, cell // m))]))

    return -1

def get_neighbors(cell, obstacles):
    rows, cols = len(cell) - 1, len(cell[0]) - 1
    results = []
    for d_row in range(-1, 2):
        for d_col in range(-1, 2):
            if abs(d_row + d_col) != 1:
                if cell[0] + d_row < 0 or cell[0] + d_row >= rows or cell[1] + d_col < 0 or cell[1] + d_col >= cols:
                    results.append((cell[0] + d_row, cell[1] + d_col))
                elif cell[0] + d_row == cell[0] + d_col and cell[1] + d_row != cell[1] + d_col and cell in obstacles:
                    results.append((cell[0] + d_row, cell[1] + d_col))

    return list(set(results))

