    limits = defaultdict(list)
    for i in range(1, 2*n + 1):
        for j in range(i+1, 2*n + 1):
            limits[min(i, j)].append((i, j, abs(i - j) + 1))
            limits[max(i, j)].append((i, j, abs(i - j) + 1))

