            _dist, i, move = dist
            cave_i, end = i % 2*n, i // 2
            cost = dist[2] - move  # The additional distance connecting the two caves
            candidates = {}
            for j in range(2 * n):
                house_i, house_end = j % 2*n, j // 2
                cost2 = dist[2] - 4*n - move + 2*(j % 2)  # Substitution to account for the endpoints problem
                if house_i == house_end:
