            palindrome_length = i - j + 1
            for k in range(1, palindrome_length + 1):
                if text.startswith(palindrome, i - k):
                    pair_count[(i - k, i)] = palindrome_length * (k - 1)
                if text.endswith(palindrome, i + k - 1):
                    palindrome_pair = tuple(sorted((i, i + k)))
                    palindrome_pairs.add(palindrome_pair)
                    pair_count[palindrome_pair] = palindrome_length * (k - 1)

    # Calculate the number of crossing pairs
