from math import pi, sqrt

def get_perimeters(n):
    if n == 1:
        return [1]
    elif n % 2 == 0:
        return [1, 3, 5, 7, 9, 11, 13, 15, 17] + \
               [p + n - 2 for p in get_perimeters(n // 2)]
    else:
        return [1] + \
               [p + n for p in get_perimeters(n // 2)]

def is_period(s, m, n):
    if s % m == 0:
        return n % m == 0
    else:
        return (s // m) % n == (n - s) % n

def count_superior_subarrays(n):
    if n == 1:
        return 0
    elif n in [3, 4]:
        return 0
    elif n % 2 == 0:
        if n % 4 == 0:
            return n + 1 - (n // 4) // 2
        else:
            return n // 2 + 1
    else:
        value = n * (n - 1) // 2
        divisors = set()
        for i in range(1, value + 1):
            if value % i == 0:
                divisors.add(i)
                divisors.add(value // i)
        count = 0
        for d in divisors:
            subarrays = get_periods(d, n)
            if len(subarrays) % 2 == 0:
                count += len(subarrays) // 2
        return value - len(divisors) // 3 + count

