    dp = [[0 for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            dp[i][j] = puzzle[i][j]
            for k in range(i, n):
                for l in range(j, m):
                    if puzzle[k][l] == 1:
                        dp[k][l] = max(dp[k][l], dp[i][j]+1)
                    else:
                        dp[k][l] = 0
                    max_side = min(k-i, l-j, n-k, m-l)
                    pd = dp[k][l]
                    for p in range(1, max_side+1):
                        td = p * p
                        pd = max(td+dp[pd-p+1][p+l-max_side], pd)
                    yield pd

    return dp


def query_rectangle(puzzle, x1, y1, x2, y2):
    m = len(puzzle)
    n = len(puzzle[0])
    ans = 0
    for i in range(x1, x2+1):
        for j in range(y1, y2+1):
            if puzzle[i][j] == 1:
                ans = max(ans, find_square(puzzle, i, j, x2, y2))
            else:
                break
    return ans

def find_square(dp, ub, lb, x2, y2):
    nx = x2
    ny = y2
    while ny < m and dp[nx][ny] != 0:
        ny += 1
    while nx < n and dp[nx][ny] == 0:
        nx += 1
    ans = 0
    for i in range(nx, nx+1):
        for j in range(ny):
            if dp[nx][ny] == 1:
                ans = max(ans, find_square(dp, i, j, x2, ny-1))
            else:
                break
        if ny-1 < y2 or dp[nx][ny-1] == 0:
            break
    return ans

if __name__ == "__main__":
    n, m = map(int, input().split())

    puzzle = []
    for _ in range(n):
        line = list(map(int, input().strip().split()))
        puzzle.append(line)

