    queue = [(0, 0)]  # (runs_count, k)
    seen = set([(0, 0)])
    min_runs = 0

    while queue:
        runs_count, current_k = heappop(queue)
        if (runs_count, current_k) in seen:
            continue
        seen.add((runs_count, current_k))

        if runs_count == n + m:
            return runs_count

        for next_k in dp[(runs_count, current_k)]:
            if len(dp[(runs_count + 1, next_k)]) == 0:
                continue
            heappush(queue, (runs_count + 1, next_k))

