import itertools
from collections import defaultdict

def process_input():
    n, m = map(int, input().split())
    roads = [list(map(int, input().split())) for _ in range(m)]
    return n, m, roads

def check_route_completion(start, end, road_map):
    stack = [(start, "")]
    while stack:
        current, expression = stack.pop()
        for possible_road in road_map[current]:
            new_expr = expression + "".join(possible_road)
            if new_expr[-1] == "B":
                if check_complete_expression(new_expr):
                    return new_expr + "B"
            elif check_complete_expression(new_expr):
                return new_expr + "P"
            else:
                stack.append((possible_road[1], new_expr + "B"))
    return ""

def check_complete_expression(expression):
    cycle = {expression[0]: 0}
    for char in expression:
        prev_c = cycle.get(char)
        if prev_c == 1 or prev_c == 2:
            cycle[char] = -1
        else:
            cycle[char] = 1
    if all(prev_c == 2 for prev_c in cycle.values() if not (cycle.get(prev_c, 0) == -1 and prev_c != next(reversed(expression), '\0'))):
        return True
    return False

def main():
    n, m, roads = process_input()
    road_map = defaultdict(list)
    for i in range(1, n + 1):
        road_map[i] = list(itertools.chain.from_iterable([(ij, t) for ij, t in roads if ij <= i]))
    ans = ""
    for i in range(1, 100):
        curr = check_route_completion(1, n, road_map)
        if curr != "":
            ans = curr[:-1] if curr.split("B")[0] < curr.split("P")[0] else curr.split("B")[1]
            break
    print(ans if ans else "-1")

if __name__ == "__main__":
